import bisect

def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be int")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list/tuple")

    n = len(transitions)
    ts = []
    offsets = [initial]
    for tr in transitions:
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("Invalid transition")
        t, off = tr
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("Transition t must be int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("Transition off must be int")
        if abs(t) > 10**13:
            raise ValueError("Transition t out of range")
        if abs(off) > 50400:
            raise ValueError("Transition off out of range")
        ts.append(t)
        offsets.append(off)

    # Validate transition ordering and constraints
    prev_t = -float('inf')
    prev_off = initial
    for i, (t, off) in enumerate(transitions):
        if t <= prev_t:
            raise ValueError("Transitions not strictly increasing")
        if i > 0 and t - prev_t < 172800:
            raise ValueError("Transitions too close")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset change too large")
        prev_t = t
        prev_off = off

    # Precompute arrays for O(log n) lookups
    starts = [t + off for t, off in transitions]  # starts[i] corresponds to offsets[i+1]
    ends_arr = [float('inf')] * (n + 1)
    if n > 0:
        ends_arr[0] = ts[0] + initial
        for i in range(1, n):
            ends_arr[i] = ts[i] + offsets[i]
        ends_arr[n] = ts[n-1] + offsets[n]

    # Validate ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops must be list/tuple")
    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("Invalid op structure")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Op name must be str")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant requires 2 args")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w must be int")
            if abs(w) > 10**13:
                raise ValueError("w out of range")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")

            # Resolve w to x
            idx = bisect.bisect_right(starts, w)
            valid = []
            # Check idx (corresponds to offsets[idx])
            if idx <= n and w < ends_arr[idx]:
                valid.append(offsets[idx])
            # Check idx-1
            if idx > 0 and w < ends_arr[idx-1]:
                valid.append(offsets[idx-1])

            if len(valid) == 0:
                # Gap
                k = bisect.bisect_left(starts, w)
                a = offsets[k-1] if k > 0 else initial
                b = offsets[k] if k < n+1 else offsets[k-1] # fallback, though k<=n usually
                # Actually gap is between k-1 and k
                if k == 0:
                    a, b = initial, offsets[1]
                else:
                    a, b = offsets[k-1], offsets[k]
                x = w - (a if fold == 0 else b)
            elif len(valid) == 1:
                x = w - valid[0]
            else:
                # Two matches
                x1 = w - valid[0]
                x2 = w - valid[1]
                x = x1 if fold == 0 else x2
                if x1 > x2:
                    x = x2 if fold == 0 else x1

            results.append(x)

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall requires 1 arg")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("x must be int")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            idx = bisect.bisect_right(ts, x)
            off = offsets[idx]
            w = x + off

            # Determine fold flag
            f = 0
            if idx > 0 and off < offsets[idx-1] and w < ts[idx-1] + offsets[idx-1]:
                f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add requires 4 args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w must be int")
            if abs(w) > 10**13:
                raise ValueError("w out of range")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("days must be int")
            if abs(days) > 10**6:
                raise ValueError("days out of range")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("secs must be int")
            if abs(secs) > 10**13:
                raise ValueError("secs out of range")

            w2 = w + 86400 * days
            # Resolve w2
            idx2 = bisect.bisect_right(starts, w2)
            valid2 = []
            if idx2 <= n and w2 < ends_arr[idx2]:
                valid2.append(offsets[idx2])
            if idx2 > 0 and w2 < ends_arr[idx2-1]:
                valid2.append(offsets[idx2-1])

            if len(valid2) == 0:
                k = bisect.bisect_left(starts, w2)
                a = offsets[k-1] if k > 0 else initial
                b = offsets[k] if k < n+1 else offsets[k-1]
                if k == 0:
                    a, b = initial, offsets[1]
                else:
                    a, b = offsets[k-1], offsets[k]
                x1 = w2 - (a if fold == 0 else b)
            elif len(valid2) == 1:
                x1 = w2 - valid2[0]
            else:
                x1a = w2 - valid2[0]
                x1b = w2 - valid2[1]
                x1 = x1a if fold == 0 else x1b
                if x1a > x1b:
                    x1 = x1b if fold == 0 else x1a

            x2 = x1 + secs
            idx3 = bisect.bisect_right(ts, x2)
            off3 = offsets[idx3]
            w_new = x2 + off3
            f_new = 0
            if idx3 > 0 and off3 < offsets[idx3-1] and w_new < ts[idx3-1] + offsets[idx3-1]:
                f_new = 1
            results.append((w_new, f_new))
        else:
            raise ValueError("Unknown operation")

    return results

