    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be int")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list or tuple")
    if len(transitions) > 100000:
        raise ValueError("Too many transitions")

    T_list = []
    off_list = [initial]
    prev_t = None
    prev_off = initial

    for entry in transitions:
        if not isinstance(entry, (list, tuple)) or len(entry) != 2:
            raise ValueError("Invalid transition entry")
        t, off = entry
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("t must be int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("off must be int")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("t or off out of range")
        if prev_t is not None and t <= prev_t + 172800:
            raise ValueError("Transitions not spaced by at least 172800")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset change exceeds 86400")
        T_list.append(t)
        off_list.append(off)
        prev_t = t
        prev_off = off

    n = len(T_list)
    T_list = tuple(T_list)
    off_list = tuple(off_list)

    # w_start[i] is the minimum wall time for interval i
    # w_end[i] is the maximum wall time for interval i (exclusive)
    w_start = [-float('inf')]
    for i in range(1, n):
        w_start.append(T_list[i-1] + off_list[i])
    # w_end[i] = T_list[i] + off_list[i] for i < n-1, inf for i == n-1
    w_end = [T_list[i] + off_list[i] for i in range(n-1)] + [float('inf')]

    def resolve(w, fold):
        if not isinstance(w, int) or isinstance(w, bool):
            raise ValueError("w must be int")
        if fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")
        if abs(w) > 10**13:
            raise ValueError("w out of range")

        idx = bisect.bisect_left(w_start, w)
        valid_xs = []
        for i in (idx - 1, idx):
            if 0 <= i < n:
                if w < w_end[i]:
                    valid_xs.append(w - off_list[i])

        if len(valid_xs) == 1:
            return valid_xs[0]
        elif len(valid_xs) == 2:
            return valid_xs[0] if fold == 0 else valid_xs[1]
        else:
            # Gap
            a = off_list[idx - 1] if idx > 0 else initial
            b = off_list[idx] if idx < n else off_list[n]
            return (w - a) if fold == 0 else (w - b)

    def get_wall(x):
        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError("x must be int")
        if abs(x) > 10**13:
            raise ValueError("x out of range")

        idx = bisect.bisect_right(T_list, x) - 1
        if idx < 0:
            off = initial
        else:
            off = off_list[idx]

        w = x + off
        f = 0
        if idx > 0 and off_list[idx] < off_list[idx-1]:
            overlap_start = T_list[idx] + off_list[idx]
            if x < overlap_start:
                f = 1
        return (w, f)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("Invalid op structure")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Op name must be str")

        if name == "instant":
            if len(op) != 3: raise ValueError("instant expects 3 args")
            w, fold = op[1], op[2]
            results.append(resolve(w, fold))
        elif name == "wall":
            if len(op) != 2: raise ValueError("wall expects 2 args")
            x = op[1]
            results.append(get_wall(x))
        elif name == "add":
            if len(op) != 5: raise ValueError("add expects 5 args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool): raise ValueError()
            if fold not in (0, 1): raise ValueError()
            if not isinstance(days, int) or isinstance(days, bool): raise ValueError()
            if not isinstance(secs, int) or isinstance(secs, bool): raise ValueError()
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError()
            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(get_wall(x2))
        else:
            raise ValueError("Unknown operation")

    return results

