def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone")
    initial, transitions = zone
    if type(initial) is not int or isinstance(initial, bool):
        raise ValueError("initial")
    if abs(initial) > 50400:
        raise ValueError("initial range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions")
    n = len(transitions)
    if n > 100000:
        raise ValueError("transitions length")

    # Build lookup arrays and validate transitions
    start_walls = [0] * n
    prev_offs = [0] * n
    transitions_t = [0] * n
    prev_off = initial
    prev_t = -float('inf')

    for i in range(n):
        tr = transitions[i]
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("transition")
        t, off = tr
        if type(t) is not int or isinstance(t, bool):
            raise ValueError("t")
        if type(off) is not int or isinstance(off, bool):
            raise ValueError("off")
        if abs(off) > 50400:
            raise ValueError("off range")
        if abs(t) > 10**13:
            raise ValueError("t range")
        if t <= prev_t:
            raise ValueError("t order")
        if t - prev_t < 172800:
            raise ValueError("t gap")
        if abs(off - prev_off) > 86400:
            raise ValueError("off diff")

        prev_offs[i] = prev_off
        transitions_t[i] = t
        start_walls[i] = t + prev_off
        prev_t = t
        prev_off = off

    # Validate ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op")
        if not isinstance(op[0], str):
            raise ValueError("op name")
        name = op[0]

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant len")
            w, fold = op[1], op[2]
            if type(w) is not int or isinstance(w, bool):
                raise ValueError("w")
            if abs(w) > 10**13:
                raise ValueError("w range")
            if type(fold) is not int or isinstance(fold, bool):
                raise ValueError("fold")
            if fold not in (0, 1):
                raise ValueError("fold")

            idx = bisect.bisect_right(start_walls, w)
            if idx == 0:
                results.append(w - initial)
            elif idx == n:
                results.append(w - transitions[-1][1])
            else:
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff > 0:
                    if start_walls[i] <= w < start_walls[i] + diff:
                        results.append(w - a if fold == 0 else w - b)
                    else:
                        results.append(w - b)
                elif diff < 0:
                    if start_walls[i] <= w <= start_walls[i] - diff:
                        results.append(w - a if fold == 0 else w - b)
                    else:
                        results.append(w - b)
                else:
                    results.append(w - b)

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall len")
            x = op[1]
            if type(x) is not int or isinstance(x, bool):
                raise ValueError("x")
            if abs(x) > 10**13:
                raise ValueError("x range")

            idx = bisect.bisect_right(transitions_t, x)
            off = initial if idx == 0 else transitions[idx-1][1]
            w = x + off
            f = 0
            if idx > 0:
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff < 0:
                    if start_walls[i] <= w <= start_walls[i] - diff:
                        if off == b:
                            f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add len")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if type(w) is not int or isinstance(w, bool):
                raise ValueError("w")
            if abs(w) > 10**13:
                raise ValueError("w range")
            if type(fold) is not int or isinstance(fold, bool):
                raise ValueError("fold")
            if fold not in (0, 1):
                raise ValueError("fold")
            if type(days) is not int or isinstance(days, bool):
                raise ValueError("days")
            if abs(days) > 10**6:
                raise ValueError("days range")
            if type(secs) is not int or isinstance(secs, bool):
                raise ValueError("secs")
            if abs(secs) > 10**13:
                raise ValueError("secs range")

            w2 = w + 86400 * days
            idx = bisect.bisect_right(start_walls, w2)
            if idx == 0:
                x1 = w2 - initial
            elif idx == n:
                x1 = w2 - transitions[-1][1]
            else:
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff > 0:
                    if start_walls[i] <= w2 < start_walls[i] + diff:
                        x1 = w2 - a if fold == 0 else w2 - b
                    else:
                        x1 = w2 - b
                elif diff < 0:
                    if start_walls[i] <= w2 <= start_walls[i] - diff:
                        x1 = w2 - a if fold == 0 else w2 - b
                    else:
                        x1 = w2 - b
                else:
                    x1 = w2 - b

            x2 = x1 + secs
            idx2 = bisect.bisect_right(transitions_t, x2)
            off2 = initial if idx2 == 0 else transitions[idx2-1][1]
            w3 = x2 + off2
            f2 = 0
            if idx2 > 0:
                i2 = idx2 - 1
                a2 = prev_offs[i2]
                b2 = transitions[i2][1]
                diff2 = b2 - a2
                if diff2 < 0:
                    if start_walls[i2] <= w3 <= start_walls[i2] - diff2:
                        if off2 == b2:
                            f2 = 1
            results.append((w3, f2))

        else:
            raise ValueError("unknown op")

    return results

import bisect

def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone")
    initial, transitions = zone
    if type(initial) is not int or isinstance(initial, bool):
        raise ValueError("initial")
    if abs(initial) > 50400:
        raise ValueError("initial range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions")
    n = len(transitions)
    if n > 100000:
        raise ValueError("transitions length")

    # Build lookup arrays and validate transitions
    start_walls = [0] * n
    prev_offs = [0] * n
    transitions_t = [0] * n
    prev_off = initial
    prev_t = -float('inf')

    for i in range(n):
        tr = transitions[i]
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("transition")
        t, off = tr
        if type(t) is not int or isinstance(t, bool):
            raise ValueError("t")
        if type(off) is not int or isinstance(off, bool):
            raise ValueError("off")
        if abs(off) > 50400:
            raise ValueError("off range")
        if abs(t) > 10**13:
            raise ValueError("t range")
        if t <= prev_t:
            raise ValueError("t order")
        if t - prev_t < 172800:
            raise ValueError("t gap")
        if abs(off - prev_off) > 86400:
            raise ValueError("off diff")

        prev_offs[i] = prev_off
        transitions_t[i] = t
        start_walls[i] = t + prev_off
        prev_t = t
        prev_off = off

    # Validate ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op")
        if not isinstance(op[0], str):
            raise ValueError("op name")
        name = op[0]

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant len")
            w, fold = op[1], op[2]
            if type(w) is not int or isinstance(w, bool):
                raise ValueError("w")
            if abs(w) > 10**13:
                raise ValueError("w range")
            if type(fold) is not int or isinstance(fold, bool):
                raise ValueError("fold")
            if fold not in (0, 1):
                raise ValueError("fold")

            idx = bisect.bisect_right(start_walls, w)

            if idx == 0:
                # w < start_walls[0] => w < T0 + a0 => x < T0
                # offset is initial (a0)
                results.append(w - initial)
            elif idx == n:
                # w >= start_walls[n-1] => w >= T_{n-1} + a_{n-1}
                # Check if in gap at last transition
                i = n - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff > 0:
                    # Gap [T+a, T+b)
                    # start_walls[i] is T+a
                    # Gap ends at start_walls[i] + diff
                    if w < start_walls[i] + diff:
                        # In gap
                        results.append(w - a if fold == 0 else w - b)
                    else:
                        # After gap, offset is b
                        results.append(w - b)
                else:
                    # No gap (diff <= 0), offset is b
                    results.append(w - b)
            else:
                # idx is between 1 and n-1
                # start_walls[idx-1] <= w < start_walls[idx]
                # This range covers transition idx-1
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a

                # Transition at T = transitions_t[i]
                # Wall time of T with offset a is start_walls[i]
                # Wall time of T with offset b is start_walls[i] + diff

                if diff > 0:
                    # Gap: [start_walls[i], start_walls[i] + diff)
                    if start_walls[i] <= w < start_walls[i] + diff:
                        # In gap
                        results.append(w - a if fold == 0 else w - b)
                    elif w < start_walls[i]:
                        # Before gap (actually impossible since w >= start_walls[i] in this branch)
                        # Wait, bisect_right ensures w >= start_walls[i] if idx > i?
                        # bisect_right returns insertion point.
                        # If w == start_walls[i], returns i+1.
                        # So if idx = i+1, w >= start_walls[i].
                        # So w < start_walls[i] is impossible here.
                        # Actually, if diff > 0, gap starts at start_walls[i].
                        # So w is either in gap or after gap.
                        # Wait, if w < start_walls[i], idx would be <= i.
                        # So here w >= start_walls[i].
                        # So we only check gap condition.
                        pass 
                    else:
                        # After gap, x >= T, offset is b
                        results.append(w - b)
                elif diff < 0:
                    # Overlap: [start_walls[i] + diff, start_walls[i]]
                    # Note diff is negative, so start_walls[i] + diff < start_walls[i]
                    if start_walls[i] + diff <= w <= start_walls[i]:
                        # In overlap
                        # If fold == 0, earlier instant (offset a) => x = w - a
                        # If fold == 1, later instant (offset b) => x = w - b
                        results.append(w - a if fold == 0 else w - b)
                    elif w < start_walls[i] + diff:
                        # Before overlap, x >= T, offset is b
                        results.append(w - b)
                    else:
                        # After overlap (w > start_walls[i]), x < T, offset is a
                        results.append(w - a)
                else:
                    # diff == 0, no gap/overlap
                    results.append(w - b)

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall len")
            x = op[1]
            if type(x) is not int or isinstance(x, bool):
                raise ValueError("x")
            if abs(x) > 10**13:
                raise ValueError("x range")

            idx = bisect.bisect_right(transitions_t, x)
            off = initial if idx == 0 else transitions[idx-1][1]
            w = x + off
            f = 0
            if idx > 0:
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff < 0:
                    # Overlap region
                    # Overlap in wall times is [T+b, T+a]
                    # T+b = start_walls[i] + diff
                    # T+a = start_walls[i]
                    if start_walls[i] + diff <= w <= start_walls[i]:
                        # x is in overlap
                        # f = 1 if x corresponds to the later instant (offset b)
                        # w = x + off. If off == b, then x is later instant.
                        if off == b:
                            f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add len")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if type(w) is not int or isinstance(w, bool):
                raise ValueError("w")
            if abs(w) > 10**13:
                raise ValueError("w range")
            if type(fold) is not int or isinstance(fold, bool):
                raise ValueError("fold")
            if fold not in (0, 1):
                raise ValueError("fold")
            if type(days) is not int or isinstance(days, bool):
                raise ValueError("days")
            if abs(days) > 10**6:
                raise ValueError("days range")
            if type(secs) is not int or isinstance(secs, bool):
                raise ValueError("secs")
            if abs(secs) > 10**13:
                raise ValueError("secs range")

            w2 = w + 86400 * days
            # Resolve w2 to x1
            idx = bisect.bisect_right(start_walls, w2)

            if idx == 0:
                x1 = w2 - initial
            elif idx == n:
                i = n - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff > 0:
                    if w2 < start_walls[i] + diff:
                        x1 = w2 - a if fold == 0 else w2 - b
                    else:
                        x1 = w2 - b
                else:
                    x1 = w2 - b
            else:
                i = idx - 1
                a = prev_offs[i]
                b = transitions[i][1]
                diff = b - a
                if diff > 0:
                    if start_walls[i] <= w2 < start_walls[i] + diff:
                        x1 = w2 - a if fold == 0 else w2 - b
                    else:
                        x1 = w2 - b
                elif diff < 0:
                    if start_walls[i] + diff <= w2 <= start_walls[i]:
                        x1 = w2 - a if fold == 0 else w2 - b
                    elif w2 < start_walls[i] + diff:
                        x1 = w2 - b
                    else:
                        x1 = w2 - a
                else:
                    x1 = w2 - b

            x2 = x1 + secs
            idx2 = bisect.bisect_right(transitions_t, x2)
            off2 = initial if idx2 == 0 else transitions[idx2-1][1]
            w3 = x2 + off2
            f2 = 0
            if idx2 > 0:
                i2 = idx2 - 1
                a2 = prev_offs[i2]
                b2 = transitions[i2][1]
                diff2 = b2 - a2
                if diff2 < 0:
                    if start_walls[i2] + diff2 <= w3 <= start_walls[i2]:
                        if off2 == b2:
                            f2 = 1
            results.append((w3, f2))

        else:
            raise ValueError("unknown op")

    return results

def gate_trace(gates, stimuli, watch, until):
    # --- Validation ---
    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")
    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple (out, op, ins, delay)")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("Gate out must be a non-empty string")
        if op not in ("AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"):
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Gate inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} gate requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} gate requires 2 to 4 inputs")
        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12:
            raise ValueError("Gate delay must be an integer 0..10**12")

    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool) or time < 0 or time > 10**12:
            raise ValueError("Stimulus time must be an integer 0..10**12")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be a non-empty string")
        if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch names must be non-empty strings")

    if not isinstance(until, int) or isinstance(until, bool) or until < 0 or until > 10**12:
        raise ValueError("until must be an integer 0..10**12")

    # --- Graph Construction & Validation ---
    all_signals = set()
    gate_map = {}
    out_names = set()
    graph = {}

    for out, op, ins, delay in gates:
        if out in out_names:
            raise ValueError("Duplicate gate output")
        out_names.add(out)
        all_signals.add(out)
        gate_map[out] = {'op': op, 'ins': list(ins), 'delay': delay}

        if out not in graph:
            graph[out] = []

        for inp in ins:
            all_signals.add(inp)
            if inp not in graph:
                graph[inp] = []
            graph[inp].append(out)

    # Cycle Detection
    color = {s: 0 for s in all_signals}
    has_cycle = False
    def dfs(u):
        nonlocal has_cycle
        if has_cycle: return
        color[u] = 1
        for v in graph.get(u, []):
            if color[v] == 1:
                has_cycle = True
                return
            if color[v] == 0:
                dfs(v)
        color[u] = 2

    for s in all_signals:
        if color[s] == 0:
            dfs(s)
            if has_cycle:
                raise ValueError("Cycle detected in gate graph")

    primary_inputs = all_signals - out_names

    for _, signal, _ in stimuli:
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input")

    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Watch name '{w}' is not a known signal")

    # --- Simulation ---
    def evaluate(op, inputs_vals):
        if op == "AND":
            return 1 if all(inputs_vals) else 0
        elif op == "OR":
            return 1 if any(inputs_vals) else 0
        elif op == "XOR":
            return 1 if sum(inputs_vals) % 2 == 1 else 0
        elif op == "NAND":
            return 0 if all(inputs_vals) else 1
        elif op == "NOR":
            return 0 if any(inputs_vals) else 1
        elif op == "NOT":
            return 1 - inputs_vals[0]
        elif op == "BUF":
            return inputs_vals[0]
        return 0

    signal_values = {s: 0 for s in all_signals}
    pending = {}  # out -> (due_time, value)

    stimuli_by_time = {}
    for time, signal, value in stimuli:
        stimuli_by_time.setdefault(time, []).append((signal, value))

    import heapq
    event_heap = [0]
    processed_times = set()

    trace = {w: [] for w in watch}
    prev_values = {w: 0 for w in watch}

    while event_heap:
        t = heapq.heappop(event_heap)
        if t in processed_times or t > until:
            continue
        processed_times.add(t)

        # Process rounds at instant t
        round_num = 0
        while True:
            round_num += 1
            changed = set()

            # Batch step
            if t in stimuli_by_time:
                for sig, val in stimuli_by_time[t]:
                    if signal_values[sig] != val:
                        changed.add(sig)
                    signal_values[sig] = val

            assignments = [(out, val) for out, (due, val) in pending.items() if due == t]
            for out, val in assignments:
                if signal_values[out] != val:
                    changed.add(out)
                signal_values[out] = val
                del pending[out]

            # Evaluate step
            if round_num == 1 and t == 0:
                gates_to_eval = list(gate_map.keys())
            else:
                gates_to_eval = [out for out, info in gate_map.items() if any(inp in changed for inp in info['ins'])]

            for out in gates_to_eval:
                info = gate_map[out]
                new_val = evaluate(info['op'], [signal_values[inp] for inp in info['ins']])
                curr_val = signal_values[out]

                if out in pending:
                    del pending[out]

                if new_val != curr_val:
                    due = t + info['delay']
                    pending[out] = (due, new_val)
                    if due <= until and due not in processed_times:
                        heapq.heappush(event_heap, due)

            # Continue rounds if assignments are due at this instant
            if not any(due == t for due, _ in pending.values()):
                break

        # Record trace after final round at instant t
        for w in watch:
            if signal_values[w] != prev_values[w]:
                trace[w].append((t, signal_values[w]))
                prev_values[w] = signal_values[w]

    return trace

