            changed_signals = set()
            assignments_at_t = [(out, val) for out, (due, val) in pending.items() if due == t]
            for out, val in assignments_at_t:
                if signal_values[out] != val:
                    changed_signals.add(out)
                signal_values[out] = val
                del pending[out]

            gates_to_eval = []
            for out_name, g_info in gate_map.items():
                # Subsequent rounds only evaluate gates with changed inputs
                if any(inp in changed_signals for inp in g_info['ins']):
                    gates_to_eval.append(out_name)

            for out_name in gates_to_eval:
                g_info = gate_map[out_name]
                input_vals = [signal_values[inp] for inp in g_info['ins']]
                new_val = evaluate(g_info['op'], input_vals)
                curr_val = signal_values[out_name]

                if out_name in pending:
                    del pending[out_name]

                if new_val != curr_val:
                    due_time = t + g_info['delay']
                    pending[out_name] = (due_time, new_val)

        # Record trace
        for w in watch:
            curr_val = signal_values[w]
            prev_val = last_values[w]
            if curr_val != prev_val:
                trace[w].append((t, curr_val))
                last_values[w] = curr_val

    return trace

