    def __init__(self, tvs, t): self.tvs = set(tvs); self.t = t

_fresh = 0
def fresh():
    global _fresh
    t = TVar(_fresh); _fresh += 1; return t

def apply_subst(t, s):
    if isinstance(t, TVar):
        while t in s:
            t = s[t]
        return t
    if isinstance(t, TList): return TList(apply_subst(t.e, s))
    if isinstance(t, TRef): return TRef(apply_subst(t.e, s))
    if isinstance(t, TArrow): 
        return TArrow(tuple(apply_subst(a, s) for a in t.args), apply_subst(t.ret, s))
    return t

def occurs(v, t, s):
    visited = set()
    stack = [t]
    while stack:
        curr = stack.pop()
        if isinstance(curr, TVar):
            while curr in s:
                if curr in visited: break 
                visited.add(curr)
                curr = s[curr]
            if curr == v: return True
            continue
        if isinstance(curr, TList): stack.append(curr.e)
        elif isinstance(curr, TRef): stack.append(curr.e)
        elif isinstance(curr, TArrow):
            stack.extend(curr.args + (curr.ret,))
    return False

