    if not isinstance(t, tuple) or not t: return False
    tag = t[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn"): return True
    if tag == "nil": return True
    if tag == "cons": return len(t) == 3 and check_value(t[1]) and check_value(t[2])
    return False

