        if isinstance(t2, TScheme):
            env_fv |= (free_vars(t2.t) - t2.tvs)
        else:
            env_fv |= free_vars(apply_subst(t2, s))
    quantified = free_vars(t) - env_fv
    return TScheme(quantified, t)

def infer(term, env, s):
    if not isinstance(term, tuple) or not term: raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed tag")

    if tag == "int":
        if len(term)!=2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError("Malformed int")
        return TInt, s
    elif tag == "bool":
        if len(term)!=2 or not isinstance(term[1], bool): raise ValueError("Malformed bool")
        return TBool, s
    elif tag == "str":
        if len(term)!=2 or not isinstance(term[1], str): raise ValueError("Malformed str")
        return TString, s
    elif tag == "unit":
        if len(term)!=1: raise ValueError("Malformed unit")
        return TUnit, s
    elif tag == "var":
        if len(term)!=2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed var")
