        ft, s = infer(f, env, s)

        arg_types = [fresh() for _ in args]
        ret_type = fresh()
        expected_ft = TArrow(tuple(arg_types), ret_type)

        s = unify(ft, expected_ft, s)

        for i, a in enumerate(args):
            at, s = infer(a, env, s)
            s = unify(at, arg_types[i], s)

        res = apply_subst(ret_type, s)
        return res, s
