        t1, s = infer(e1, env, s)
        t1 = apply_subst(t1, s)
        if check_value(e1):
            t1 = generalize(t1, env, s)
        new_env = {**env, name: t1}
        return infer(e2, new_env, s)
    elif tag == "letrec":
        if len(term)!=4: raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(e1, tuple) or not e1 or e1[0] != "fn": raise ValueError("letrec requires fn")
        ntype = fresh()
        t1, s = infer(e1, {**env, name: ntype}, s)
        t1 = apply_subst(t1, s)
        if not isinstance(t1, TArrow): raise ValueError("letrec body must be function")
        s = unify(ntype, t1, s)
        ntype = apply_subst(ntype, s)
        ntype = generalize(ntype, env, s)
        new_env = {**env, name: ntype}
        return infer(e2, new_env, s)
    elif tag == "nil":
        if len(term)!=1: raise ValueError("Malformed nil")
        return TList(fresh()), s
    elif tag == "cons":
        if len(term)!=3: raise ValueError("Malformed cons")
        h, t = term[1], term[2]
        ht, s = infer(h, env, s)
        tt, s = infer(t, env, s)
        lt = TList(ht)
        s = unify(tt, lt, s)
        res = apply_subst(lt, s)
        return res, s
    elif tag == "match":
