        s_term, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn: raise ValueError("Malformed match names")
        if hn == tn: raise ValueError("Match names must differ")
        st, s = infer(s_term, env, s)
        st = apply_subst(st, s)
        if not isinstance(st, TList): raise ValueError("Match requires List")
        elem = st.e
        new_env = {**env, hn: elem, tn: st}
        tn1, s = infer(e_nil, new_env, s)
        tn2, s = infer(e_cons, new_env, s)
        s = unify(tn1, tn2, s)
        res = apply_subst(tn1, s)
        return res, s
    elif tag == "ref":
        if len(term)!=2: raise ValueError("Malformed ref")
        et, s = infer(term[1], env, s)
        res = TRef(et)
        return apply_subst(res, s), s
    elif tag == "get":
        if len(term)!=2: raise ValueError("Malformed get")
        rt, s = infer(term[1], env, s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef): raise ValueError("Get requires Ref")
        res = rt.e
        return apply_subst(res, s), s
    elif tag == "set":
        if len(term)!=3: raise ValueError("Malformed set")
        r, e = term[1], term[2]
        rt, s = infer(r, env, s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef): raise ValueError("Set requires Ref")
        et, s = infer(e, env, s)
        s = unify(et, rt.e, s)
        return TUnit, s
    else:
        raise ValueError("Unknown tag")

