        env_x = {**env, x: (gen_type, quantified)}
        e2_type, s2 = infer(e2, env_x, fresh_counter)
        s = combine_subst(s1, s2)
        return apply_subst(e2_type, s), s

    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Bad letrec length")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Bad letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n: raise ValueError("Bad letrec name")
            if n in names: raise ValueError("Duplicate letrec name")
            names.append(n)
            exprs.append(e)

        temp_env = {**env}
        name_types = {}
        for n in names:
            fresh_name = next_var_name(fresh_counter[0])
            fresh_counter[0] += 1
            temp_env[n] = (Type('Var', fresh_name), set())
            name_types[n] = Type('Var', fresh_name)

        inferred_types = []
        for e in exprs:
            t, s = infer(e, temp_env, fresh_counter)
            inferred_types.append(t)

        s = {}
        for n, t in zip(names, inferred_types):
            s = unify(name_types[n], t, s)

        final_types = [apply_subst(t, s) for t in inferred_types]

        env_fv = set()
        for t, _ in env.values():
            env_fv.update(free_vars(t))

        gen_env = {**env}
        for n, t in zip(names, final_types):
            gen_type, quantified = generalize(t, env_fv)
            gen_env[n] = (gen_type, quantified)

        body_type, s2 = infer(body, gen_env, fresh_counter)
        s = combine_subst(s, s2)
        return apply_subst(body_type, s), s

    elif tag == "tuple":
        if len(term) < 1: raise ValueError("Bad tuple")
        n = len(term) - 1
        if n == 1: raise ValueError("Tuple n=1 not allowed")
        types = []
        s = {}
        for i in range(1, len(term)):
            t, si = infer(term[i], env, fresh_counter)
            types.append(t)
            s = combine_subst(s, si)
        return Type('Tuple', *(apply_subst(t, s) for t in types)), s

    elif tag == "proj":
        if len(term) != 4: raise ValueError("Bad proj")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Bad proj i")
        if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Bad proj n")
        if n < 2: raise ValueError("proj n < 2")
        if i < 0 or i >= n: raise ValueError("proj i out of bounds")
        e_type, s = infer(e, env, fresh_counter)
        if e_type.tag != 'Tuple' or len(e_type.args) != n:
            raise ValueError("proj type mismatch")
        return e_type.args[i], s

    else:
        raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    init_env = {
        "add": (Type('Arrow', Type('Int'), Type('Arrow', Type('Int'), Type('Int'))), set()),
        "eq": (Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('Var', 'a'), Type('Bool'))), {'a'}),
        "nil": (Type('List', Type('Var', 'a')), {'a'}),
        "cons": (Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a')))), {'a'}),
        "head": (Type('Arrow', Type('List', Type('Var', 'a')), Type('Var', 'a')), {'a'}),
        "tail": (Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a'))), {'a'}),
        "isnil": (Type('Arrow', Type('List', Type('Var', 'a')), Type('Bool')), {'a'}),
    }
    fresh_counter = [0]
    res, _ = infer(term, init_env, fresh_counter)

    order = collect_order_vars(res)
    new_names = [next_var_name(i) for i in range(len(order))]
    mapping = {old: new for old, new in zip(order, new_names)}
    res = rename_vars(res, mapping)

    return format_type(res)

import sys
sys.setrecursionlimit(10000)

class Type:
    __slots__ = ('tag', 'args', 'name')
    def __init__(self, tag, *args):
        self.tag = tag
        self.args = args
        self.name = args[0] if tag == 'Var' else None
    def __eq__(self, other):
        return isinstance(other, Type) and self.tag == other.tag and self.args == other.args
    def __hash__(self):
        return hash((self.tag, self.args))
    def __repr__(self):
        return f"Type({self.tag}, {self.args})"

def next_fresh_name(i):
    res = []
    i += 1
    while i > 0:
        i, rem = divmod(i - 1, 26)
        res.append(chr(ord('a') + rem))
    return ''.join(reversed(res))

def apply_subst(t, s):
    if t.tag == 'Var':
        return s.get(t.name, t)
    if t.tag == 'Arrow':
        return Type('Arrow', apply_subst(t.args[0], s), apply_subst(t.args[1], s))
    if t.tag == 'List':
        return Type('List', apply_subst(t.args[0], s))
    if t.tag == 'Tuple':
        return Type('Tuple', *(apply_subst(a, s) for a in t.args))
    return t

def free_vars(t):
    if t.tag == 'Var':
        return {t.name}
    if t.tag == 'Arrow':
        return free_vars(t.args[0]) | free_vars(t.args[1])
    if t.tag == 'List':
        return free_vars(t.args[0])
    if t.tag == 'Tuple':
        fv = set()
        for a in t.args:
            fv |= free_vars(a)
        return fv
    return set()

def occurs_in(name, t, s):
    t = apply_subst(t, s)
    if t.tag == 'Var':
        return t.name == name
    return any(occurs_in(name, a, s) for a in t.args)

def unify(t1, t2, s):
    t1 = apply_subst(t1, s)
    t2 = apply_subst(t2, s)
    if t1 == t2:
        return s
    if t1.tag == 'Var':
        if occurs_in(t1.name, t2, s):
            raise ValueError("Infinite type")
        return {**s, t1.name: t2}
    if t2.tag == 'Var':
        if occurs_in(t2.name, t1, s):
            raise ValueError("Infinite type")
        return {**s, t2.name: t1}
    if t1.tag == 'Arrow' and t2.tag == 'Arrow':
        s = unify(t1.args[0], t2.args[0], s)
        return unify(t1.args[1], t2.args[1], s)
    if t1.tag == 'List' and t2.tag == 'List':
        return unify(t1.args[0], t2.args[0], s)
    if t1.tag == 'Tuple' and t2.tag == 'Tuple':
        if len(t1.args) != len(t2.args):
            raise ValueError("Tuple size mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            s = unify(a1, a2, s)
        return s
    raise ValueError("Type mismatch")

def collect_order_vars(t):
    seen = set()
    order = []
    def traverse(t):
        if t.tag == 'Var':
            if t.name not in seen:
                seen.add(t.name)
                order.append(t.name)
        elif t.tag == 'Arrow':
            traverse(t.args[0])
            traverse(t.args[1])
        elif t.tag == 'List':
            traverse(t.args[0])
        elif t.tag == 'Tuple':
            for a in t.args:
                traverse(a)
    traverse(t)
    return order

def rename_vars(t, mapping):
    if t.tag == 'Var':
        return Type('Var', mapping.get(t.name, t.name))
    if t.tag == 'Arrow':
        return Type('Arrow', rename_vars(t.args[0], mapping), rename_vars(t.args[1], mapping))
    if t.tag == 'List':
        return Type('List', rename_vars(t.args[0], mapping))
    if t.tag == 'Tuple':
        return Type('Tuple', *(rename_vars(a, mapping) for a in t.args))
    return t

def format_type(t):
    if t.tag == 'Int':
        return 'Int'
    if t.tag == 'Bool':
        return 'Bool'
    if t.tag == 'Var':
        return t.name
    if t.tag == 'Arrow':
        return f"(-> {format_type(t.args[0])} {format_type(t.args[1])})"
    if t.tag == 'List':
        return f"(List {format_type(t.args[0])})"
    if t.tag == 'Tuple':
        if len(t.args) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(format_type(a) for a in t.args)})"
    raise ValueError(f"Unknown type tag: {t.tag}")

def infer(term, env, fresh_counter, s):
    if isinstance(term, int) and not isinstance(term, bool):
        return Type('Int'), s
    if term is True or term is False:
        return Type('Bool'), s
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        if term in env:
            t, poly = env[term]
            if poly is not None:
                subst = {}
                for v in poly:
                    fresh_counter[0] += 1
                    subst[v] = Type('Var', next_fresh_name(fresh_counter[0]))
                t = apply_subst(t, subst)
            return t, s
        raise ValueError(f"Unbound variable: {term}")
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Bad tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Bad lam length")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x: raise ValueError("Bad param name")
        fresh_counter[0] += 1
        x_type = Type('Var', next_fresh_name(fresh_counter[0]))
        env_x = {**env, x: (x_type, None)}
        body_type, s1 = infer(body, env_x, fresh_counter, s)
        return Type('Arrow', x_type, body_type), s1

    elif tag == "app":
        if len(term) != 3: raise ValueError("Bad app length")
        f, a = term[1], term[2]
        f_type, s1 = infer(f, env, fresh_counter, s)
        a_type, s2 = infer(a, env, fresh_counter, s1)
        fresh_counter[0] += 1
        res_type = Type('Var', next_fresh_name(fresh_counter[0]))
        s3 = unify(f_type, Type('Arrow', a_type, res_type), s2)
        return apply_subst(res_type, s3), s3

    elif tag == "if":
        if len(term) != 4: raise ValueError("Bad if length")
        c, t, e = term[1], term[2], term[3]
        c_type, s1 = infer(c, env, fresh_counter, s)
        t_type, s2 = infer(t, env, fresh_counter, s1)
        e_type, s3 = infer(e, env, fresh_counter, s2)
        s4 = unify(t_type, e_type, s3)
        s5 = unify(c_type, Type('Bool'), s4)
        return apply_subst(t_type, s5), s5

    elif tag == "let":
        if len(term) != 4: raise ValueError("Bad let length")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x: raise ValueError("Bad let name")
        e1_type, s1 = infer(e1, env, fresh_counter, s)
        env_fv = set()
        for t, _ in env.values():
            env_fv |= free_vars(t)
        fv = free_vars(e1_type)
        quantified = fv - env_fv
        gen_env = {**env}
        gen_env[x] = (e1_type, quantified if quantified else None)
        e2_type, s2 = infer(e2, gen_env, fresh_counter, s1)
        return apply_subst(e2_type, s2), s2

    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Bad letrec length")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Bad letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n: raise ValueError("Bad letrec name")
            if n in names: raise ValueError("Duplicate letrec name")
            names.append(n)
            exprs.append(e)

        temp_env = {**env}
        name_types = {}
        for n in names:
            fresh_counter[0] += 1
            t = Type('Var', next_fresh_name(fresh_counter[0]))
            temp_env[n] = (t, None)
            name_types[n] = t

        inferred = []
        cur_s = s
        for e in exprs:
            t, s_new = infer(e, temp_env, fresh_counter, cur_s)
            inferred.append(t)
            cur_s = s_new

        unify_s = {}
        for n, t in zip(names, inferred):
            unify_s = unify(name_types[n], t, unify_s)

        final_types = [apply_subst(t, unify_s) for t in inferred]

        env_fv = set()
        for t, _ in env.values():
            env_fv |= free_vars(t)

        gen_env = {**env}
        for n, t in zip(names, final_types):
            fv = free_vars(t)
            quantified = fv - env_fv
            gen_env[n] = (t, quantified if quantified else None)

        body_type, s2 = infer(body, gen_env, fresh_counter, unify_s)
        return apply_subst(body_type, s2), s2

    elif tag == "tuple":
        if len(term) < 1: raise ValueError("Bad tuple")
        n = len(term) - 1
        if n == 1: raise ValueError("Tuple n=1 not allowed")
        types = []
        cur_s = s
        for i in range(1, len(term)):
            t, s_new = infer(term[i], env, fresh_counter, cur_s)
            types.append(t)
            cur_s = s_new
        return Type('Tuple', *(apply_subst(t, cur_s) for t in types)), cur_s

    elif tag == "proj":
        if len(term) != 4: raise ValueError("Bad proj")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Bad proj i")
        if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Bad proj n")
        if n < 2: raise ValueError("proj n < 2")
        if i < 0 or i >= n: raise ValueError("proj i out of bounds")
        e_type, s1 = infer(e, env, fresh_counter, s)
        if e_type.tag != 'Tuple' or len(e_type.args) != n:
            raise ValueError("proj type mismatch")
        return apply_subst(e_type.args[i], s1), s1

    else:
        raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    init_env = {
        "add": (Type('Arrow', Type('Int'), Type('Arrow', Type('Int'), Type('Int'))), set()),
        "eq": (Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('Var', 'a'), Type('Bool'))), {'a'}),
        "nil": (Type('List', Type('Var', 'a')), {'a'}),
        "cons": (Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a')))), {'a'}),
        "head": (Type('Arrow', Type('List', Type('Var', 'a')), Type('Var', 'a')), {'a'}),
        "tail": (Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a'))), {'a'}),
        "isnil": (Type('Arrow', Type('List', Type('Var', 'a')), Type('Bool')), {'a'}),
    }
    fresh_counter = [0]
    res, _ = infer(term, init_env, fresh_counter, {})

    order = collect_order_vars(res)
    new_names = [next_fresh_name(i) for i in range(len(order))]
    mapping = {old: new for old, new in zip(order, new_names)}
    res = rename_vars(res, mapping)

    return format_type(res)

import sys
from collections import deque

sys.setrecursionlimit(100000)

def branch_influence(n, edges, entry, exits, targets):
    # Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits must be a list, tuple or set")
    for x in exits:
        if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
            raise ValueError("exits must be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("targets must be a list, tuple or set")
    for x in targets:
        if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
            raise ValueError("targets must be a list, tuple or set of ints in 0..n-1")

    # Build adjacency lists
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        radj[v].append(u)

    # Compute R: reachable from entry
    R = set()
    q = deque([entry])
    R.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # Filter to R
    adj_r = [[] for _ in range(n)]
    radj_r = [[] for _ in range(n)]
    for u in R:
        for v in adj[u]:
            if v in R:
                adj_r[u].append(v)
                radj_r[v].append(u)

    # Compute A: nodes in R that can reach END
    # END is virtual. Exits have implicit edge to END.
    # We compute nodes that can reach any exit (which implies reaching END).
    # Actually, A = {u in R | u can reach some node in exits}
    # But wait, definition: "A is the set of nodes of R from which END can be reached."
    # Since exits have implicit edge to END, u can reach END iff u can reach some exit.
    can_reach_exit = set()
    q = deque([x for x in exits if x in R])
    for x in q:
        can_reach_exit.add(x)
    while q:
        u = q.popleft()
        for v in radj_r[u]:
            if v not in can_reach_exit:
                can_reach_exit.add(v)
                q.append(v)

    A = R & can_reach_exit

    # Targets outside A
    targets_outside_A = sorted([t for t in targets if t not in A])

    # If no targets in A, return early
    T = [t for t in targets if t in A]
    if not T:
        return ([], targets_outside_A)

    # Build graph for A + virtual END
    # We need post-dominator tree of original graph restricted to A.
    # This is equivalent to dominator tree of reversed graph rooted at END.
    # Nodes in A ∪ {END}. END is node n (virtual).
    # Edges in reversed graph: for each u->v in original, add v->u.
    # Plus implicit edges: for each exit x in A, add END -> x.

    # Map A nodes to 0..|A|-1 for easier indexing, or just use 0..n with n as END.
    # Using 0..n with n as END is easier.

    n_nodes = n + 1
    rev_adj = [[] for _ in range(n_nodes)]
    for u in A:
        for v in adj_r[u]:
            if v in A:
                rev_adj[v].append(u)
    for x in exits:
        if x in A:
            rev_adj[n].append(x)

    # Compute dominator tree for reversed graph rooted at n (END)
    # Using Lengauer-Tarjan algorithm
    # DFS to get tree, id, parent, semi, ancestor, val
    dfs_order = []
    parent_d = [-1] * n_nodes
    semi = [-1] * n_nodes
    ancestor = [-1] * n_nodes
    val = [-1] * n_nodes
    id_map = [-1] * n_nodes
    id_counter = 0

    # Iterative DFS to avoid recursion limit issues
    stack = [(n, 0)]
    visited = [False] * n_nodes
    visited[n] = True
    while stack:
        u, idx = stack[-1]
        if idx < len(rev_adj[u]):
            v = rev_adj[u][idx]
            stack[-1] = (u, idx + 1)
            if not visited[v]:
                visited[v] = True
                parent_d[v] = u
                id_map[v] = id_counter
                id_counter += 1
                dfs_order.append(v)
                stack.append((v, 0))
        else:
            stack.pop()

    # Initialize semi, ancestor, val
    for v in dfs_order:
        semi[v] = v
        ancestor[v] = -1
        val[v] = v

    # DSU for evaluation
    dsu_parent = list(range(n_nodes))
    dsu_min_semi = list(range(n_nodes)) # stores semi of the node with min semi in the path

    def dsu_find(i, path_compression=True):
        if dsu_parent[i] == i:
            return i
        root = dsu_find(dsu_parent[i], path_compression)
        if path_compression:
            dsu_parent[i] = root
            # Update min_semi along the path
            semi_i = semi[i]
            semi_root = semi[root]
            if semi_i < semi_root:
                dsu_min_semi[i] = dsu_min_semi[root]
                dsu_min_semi[root] = semi_i
            else:
                dsu_min_semi[i] = dsu_min_semi[root]
        return root

    def dsu_link(a, b):
        dsu_parent[a] = b
        # Update min_semi of b to be min of semi[a] and semi[b]
        if semi[a] < semi[b]:
            dsu_min_semi[b] = dsu_min_semi[a]

    def dsu_eval(v):
        dsu_find(v, path_compression=True)
        return dsu_min_semi[v]

    # Process in reverse DFS order
    for v in reversed(dfs_order):
        for u in rev_adj[v]:
            if id_map[u] != -1: # u is visited
                if semi[u] < semi[v]:
                    semi[v] = semi[u]
                else:
                    b = dsu_eval(u)
                    if semi[b] < semi[v]:
                        semi[v] = semi[b]
        if parent_d[v] != -1:
            dsu_link(v, parent_d[v])
            ancestor[v] = dsu_find(parent_d[v], path_compression=False)

    # Compute idom
    idom = [-1] * n_nodes
    for v in reversed(dfs_order):
        w = ancestor[v]
        if w == -1:
            continue
        u = dsu_eval(v)
        if semi[u] == semi[v]:
            idom[v] = semi[v]
        else:
            idom[v] = v # placeholder, will fix later

    for v in dfs_order:
        if idom[v] == v:
            if semi[idom[v]] == semi[v]:
                idom[v] = semi[v]
            else:
                idom[v] = idom[idom[v]]

    # idom now contains post-dominator tree (rooted at END)
    # Build PDT as adjacency list
    ptd_adj = [[] for _ in range(n_nodes)]
    for v in range(n):
        if idom[v] != -1 and idom[v] != v:
            ptd_adj[idom[v]].append(v)

    # Compute has_good_successor for each node in A
    # x has good successor if exists s in succ(x) such that s is ancestor of x in PDT
    # We can compute this by marking ancestors of each successor
    # But easier: for each x, check successors. If any successor is ancestor of x in PDT, mark x.
    # To check ancestor efficiently, use entry/exit times of PDT.

    ptd_entry = [-1] * n_nodes
    ptd_exit = [-1] * n_nodes
    ptd_timer = 0

    def ptd_dfs(u):
        nonlocal ptd_timer
        ptd_entry[u] = ptd_timer
        ptd_timer += 1
        for v in ptd_adj[u]:
            ptd_dfs(v)
        ptd_exit[u] = ptd_timer - 1

    ptd_dfs(n)

    def is_ancestor(u, v):
        # u is ancestor of v in PDT
        return ptd_entry[u] <= ptd_entry[v] and ptd_exit[u] >= ptd_exit[v]

    has_good = [False] * n_nodes
    for x in A:
        for s in adj_r[x]:
            if s in A:
                if is_ancestor(s, x):
                    has_good[x] = True
                    break

    # Compute C: nodes in A that are descendants of some t in T in PDT, and have has_good[x] = True
    # Actually, C = {x in A | has_good[x] and x is descendant of some t in T in PDT}
    # We can compute this by checking for each x if it's covered by any t in T.

    # To do this efficiently, we can use the entry/exit times.
    # x is descendant of t iff ptd_entry[t] <= ptd_entry[x] <= ptd_exit[t].
    # We can sort T by entry time and use a sweep line or simply iterate.
    # Since n=40k, O(n log n) is fine.

    T_sorted = sorted(T, key=lambda t: ptd_entry[t])
    # For each x, we want to know if there exists t in T such that ptd_entry[t] <= ptd_entry[x] <= ptd_exit[t].
    # This is a 1D range stabbing query.
    # We can process nodes in order of ptd_entry.
    # Use a pointer for T_sorted.

    C = []
    t_idx = 0
    # We need to check for each x in A.
    # Sort A by entry time
    A_sorted = sorted(A, key=lambda x: ptd_entry[x])

    for x in A_sorted:
        # Advance t_idx to find t with ptd_entry[t] <= ptd_entry[x]
        while t_idx < len(T_sorted) and ptd_entry[T_sorted[t_idx]] <= ptd_entry[x]:
            t_idx += 1
        # Check T_sorted[t_idx-1]
        if t_idx > 0:
            t = T_sorted[t_idx-1]
            if ptd_exit[t] >= ptd_entry[x]:
                if has_good[x]:
                    C.append(x)

    return (sorted(C), targets_outside_A)

