def branch_influence(n, edges, entry, exits, targets):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1 (bool is not an int)")
    if not isinstance(entry, int) or isinstance(entry, bool) or entry < 0 or entry >= n:
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2)")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits must be a list, tuple or set of ints in 0..n-1")
    for x in exits:
        if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
            raise ValueError("exits must be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("targets must be a list, tuple or set of ints in 0..n-1")
    for x in targets:
        if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
            raise ValueError("targets must be a list, tuple or set of ints in 0..n-1")

    # Build adjacency and reverse adjacency
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Find reachable nodes R from entry
    R = [False] * n
    stack = [entry]
    R[entry] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not R[v]:
                R[v] = True
                stack.append(v)

    # Add implicit END node (index n)
    END = n
    adj.append([])
    rev_adj.append([])
    for x in exits:
        if R[x]:
            adj[x].append(END)
            rev_adj[END].append(x)

    # Find A: nodes in R from which END is reachable
    A = [False] * (n + 1)
    A[END] = True
    stack = [END]
    while stack:
        u = stack.pop()
        for v in rev_adj[u]:
            if not A[v]:
                A[v] = True
                stack.append(v)

    A_set = set()
    A_list = []
    for i in range(n):
        if A[i] and R[i]:
            A_set.add(i)
            A_list.append(i)
    A_list.sort()

    # Build filtered adjacency for A ∪ {END}
    adj_filtered = [[] for _ in range(n + 1)]
    for x in A_list:
        for v in adj[x]:
            if A[v]:
                adj_filtered[x].append(v)
    adj_filtered[END] = []

    # Compute post-dominator tree iteratively
    IDOM = [0] * (n + 1)
    depth = [0] * (n + 1)
    IDOM[END] = END
    depth[END] = 0
    for x in A_list:
        if adj_filtered[x]:
            IDOM[x] = adj_filtered[x][0]
            depth[x] = 1
        else:
            IDOM[x] = END
            depth[x] = 1

    changed = True
    while changed:
        changed = False
        for x in A_list:
            if x == END:
                continue
            succs = adj_filtered[x]
            if not succs:
                continue
            new_idom = succs[0]
            for s in succs[1:]:
                u, v = new_idom, s
                while depth[u] > depth[v]:
                    u = IDOM[u]
                while depth[v] > depth[u]:
                    v = IDOM[v]
                while u != v:
                    u = IDOM[u]
                    v = IDOM[v]
                new_idom = u
            if IDOM[x] != new_idom:
                IDOM[x] = new_idom
                depth[x] = depth[new_idom] + 1
                changed = True

    # Compute DFS entry/exit times for O(1) ancestor queries in PD tree
    entry = [0] * (n + 1)
    exit_time = [0] * (n + 1)
    timer = 0
    stack = [(END, False)]
    while stack:
        u, visited = stack.pop()
        if not visited:
            if entry[u] == 0:
                timer += 1
                entry[u] = timer
                stack.append((u, True))
                children = [v for v in A_list if IDOM[v] == u]
                for v in reversed(children):
                    stack.append((v, False))
        else:
            exit_time[u] = timer

    def is_ancestor(u, v):
        return entry[u] <= entry[v] and exit_time[u] >= exit_time[v]

    # Compute control dependence
    controllers = [set() for _ in range(n + 1)]
    for x in A_list:
        for s in adj_filtered[x]:
            curr = s
            while curr != END:
                if curr == x or not is_ancestor(curr, x):
                    controllers[curr].add(x)
                else:
                    break
                curr = IDOM[curr]

    # Compute C: closure
    C = set()
    queue = [t for t in targets if t in A_set]
    head = 0
    while head < len(queue):
        y = queue[head]
        head += 1
        if y in C:
            continue
        C.add(y)
        for x in controllers[y]:
            if x not in C:
                queue.append(x)

    targets_outside_A = sorted([t for t in targets if t not in A_set])
    return (sorted(C), targets_outside_A)

