from collections import deque

def live_phi_sites(n, edges, entry, blocks, params):
    # Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or entry < 0 or entry >= n:
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be pairs")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not isinstance(e[1], int) or isinstance(e[1], bool):
            raise ValueError("edge endpoints must be ints")
        if e[0] < 0 or e[0] >= n or e[1] < 0 or e[1] >= n:
            raise ValueError("edge endpoints must be in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or k < 0 or k >= n:
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists/tuples")
        for instr in v:
            if not isinstance(instr, (list, tuple)) or len(instr) != 2:
                raise ValueError("instructions must be pairs")
            if instr[0] not in ('use', 'def', 'upd'):
                raise ValueError("op must be use, def, or upd")
            if not isinstance(instr[1], str) or not instr[1]:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params must be non-empty str")

    # Build adjacency lists
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Reachability
    reachable = set()
    q = deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    # Filter blocks to reachable
    reachable_blocks = {u: blocks[u] for u in reachable if u in blocks}

    # Build pred for reachable nodes
    pred = [[] for _ in range(n)]
    for u in reachable:
        for v in adj[u]:
            if v in reachable:
                pred[v].append(u)

    # Lengauer-Tarjan Dominators
    dfn = [-1] * n
    dfs_order = []
    parent = [-1] * n

    stack = [entry]
    dfn[entry] = 0
    dfs_order.append(entry)
    while stack:
        u = stack[-1]
        pushed = False
        for v in adj[u]:
            if dfn[v] == -1:
                dfn[v] = len(dfs_order)
                parent[v] = u
                dfs_order.append(v)
                stack.append(v)
                pushed = True
                break
        if not pushed:
            stack.pop()

    semi = [dfn[u] if dfn[u] != -1 else n for u in range(n)]
    ancestor = list(range(n))
    idom = [-1] * n
    bucket = [[] for _ in range(n)]
    uf = list(range(n))

    def find(v):
        if uf[v] == v:
            return v
        root = find(uf[v])
        if semi[ancestor[uf[v]]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[uf[v]]
        uf[v] = root
        return root

    def link(u, v):
        uf[v] = u
        if semi[ancestor[u]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[u]

    # Semi-dominators
    for i in range(len(dfs_order) - 1, 0, -1):
        v = dfs_order[i]
        for u in pred[v]:
            if dfn[u] == -1:
                continue
            if dfn[u] < dfn[v]:
                if dfn[u] < semi[v]:
                    semi[v] = dfn[u]
            else:
                if semi[find(u)] < semi[v]:
                    semi[v] = semi[find(u)]

    # Dominators
    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        p = parent[v]
        link(p, v)
        for w in bucket[p]:
            wsemi = semi[find(w)]
            if wsemi < semi[w]:
                idom[w] = find(w)
            else:
                idom[w] = p

    # Fix dominators
    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # Dominance Frontier
    df = [set() for _ in range(n)]
    for v in dfs_order:
        if v == entry:
            continue
        w = v
        p = idom[v]
        while w != p:
            df[w].add(v)
            w = idom[w]

    # Collect all names
    all_names = set(params)
    for instr_list in reachable_blocks.values():
        for _, name in instr_list:
            all_names.add(name)

    phi_by_node = {}

    for x in all_names:
        # D(x)
        D_x = set()
        Use_x_live = set()
        Def_x_live = set()

        for node, instrs in reachable_blocks.items():
            seen_def = False
            for op, name in instrs:
                if name == x:
                    if op in ('def', 'upd'):
                        seen_def = True
                        Def_x_live.add(node)
                    if op in ('use', 'upd') and not seen_def:
                        Use_x_live.add(node)

        if x in params:
            D_x.add(entry)
            # Implicit param assignment does not block liveness
            if entry in Def_x_live:
                Def_x_live.discard(entry)

        # P(x) via BFS on DF graph
        P_x = set(D_x)
        q = deque(P_x)
        while q:
            u = q.popleft()
            for v in df[u]:
                if v not in P_x:
                    P_x.add(v)
                    q.append(v)

        # Liveness via BFS on reverse graph
        live_x = set(Use_x_live)
        q = deque(Use_x_live)
        while q:
            u = q.popleft()
            for v in rev_adj[u]:
                if v not in reachable:
                    continue
                if v not in live_x and v not in Def_x_live:
                    live_x.add(v)
                    q.append(v)

        # Intersection
        phi_nodes = P_x & live_x
        if phi_nodes:
            if x not in phi_by_node:
                phi_by_node[x] = set()
            phi_by_node[x].update(phi_nodes)

    # Format output
    node_phis = {}
    for x, nodes in phi_by_node.items():
        for node in nodes:
            if node not in node_phis:
                node_phis[node] = []
            node_phis[node].append(x)

    result = []
    for node in sorted(node_phis.keys()):
        result.append((node, sorted(node_phis[node])))

    return result

