def format_sigfigs(s, sig, mode):
    # Validate inputs
    if not isinstance(s, str) or len(s) > 100000:
        raise ValueError("s must be a string of length <= 100000")
    if not isinstance(sig, int) or isinstance(sig, bool) or not (1 <= sig <= 2000):
        raise ValueError("sig must be an int in 1..2000")
    valid_modes = {"nearest_even", "nearest_away", "nearest_zero", "toward_zero", 
                   "away_zero", "toward_neg", "toward_pos", "zero_five"}
    if mode not in valid_modes:
        raise ValueError("invalid mode")

    # Parse sign
    idx = 0
    sign = '+'
    if s[0] in '+-':
        sign = s[0]
        idx = 1

    # Find exponent part
    e_idx = -1
    for i in range(idx, len(s)):
        if s[i] in 'eE':
            e_idx = i
            break

    if e_idx != -1:
        mantissa_str = s[idx:e_idx]
        exp_str = s[e_idx+1:]
    else:
        mantissa_str = s[idx:]
        exp_str = "0"

    # Validate and parse exponent
    if not exp_str:
        raise ValueError("invalid exponent format")
    if exp_str[0] in '+-':
        exp_sign = exp_str[0]
        exp_digits = exp_str[1:]
    else:
        exp_sign = '+'
        exp_digits = exp_str

    if not exp_digits.isdigit() or len(exp_digits) < 1 or len(exp_digits) > 10:
        raise ValueError("invalid exponent digits")
    exp_val = int(exp_digits)
    if exp_sign == '-':
        exp_val = -exp_val

    # Parse mantissa
    if '.' in mantissa_str:
        dot_idx = mantissa_str.index('.')
        int_part = mantissa_str[:dot_idx]
        frac_part = mantissa_str[dot_idx+1:]
    else:
        int_part = mantissa_str
        frac_part = ""

    if not int_part and not frac_part:
        raise ValueError("mantissa must contain at least one digit")

    digits_str = int_part + frac_part
    digits = [int(c) for c in digits_str]
    n_digits = len(digits)

    # Find first non-zero digit
    first_nz = None
    for i, d in enumerate(digits):
        if d != 0:
            first_nz = i
            break

    # Zero value handling
    if first_nz is None:
        if sig > 1:
            mantissa_out = "0." + "0" * (sig - 1)
        else:
            mantissa_out = "0"
        return f"{mantissa_out}e+00"

    # Calculate exponent of the first significant digit
    len_int_part = len(int_part)
    E = len_int_part - 1 - first_nz + exp_val

    # Determine range of digits to keep
    start_idx = first_nz
    end_idx = first_nz + sig

    if end_idx <= n_digits:
        keep_digits = digits[start_idx:end_idx]
        drop_digits = digits[end_idx:]
    else:
        keep_digits = digits[start_idx:] + [0] * (sig - len(digits[start_idx:]))
        drop_digits = []

    if not drop_digits:
        do_round_up = False
    else:
        drop_str = "".join(str(d) for d in drop_digits)
        all_zero = drop_str == "0" * len(drop_digits)

        if all_zero:
            do_round_up = False
        else:
            len_drop = len(drop_digits)
            thresh_str = "5" + "0" * (len_drop - 1)
            is_above = drop_str > thresh_str
            is_half = drop_str == thresh_str

            if mode == "toward_zero":
                do_round_up = False
            elif mode == "away_zero":
                do_round_up = True
            elif mode == "toward_neg":
                do_round_up = (sign == '-')
            elif mode == "toward_pos":
                do_round_up = (sign == '+')
            elif mode == "nearest_even":
                do_round_up = is_above or (is_half and keep_digits[-1] % 2 != 0)
            elif mode == "nearest_away":
                do_round_up = is_above or is_half
            elif mode == "nearest_zero":
                do_round_up = is_above
            elif mode == "zero_five":
                do_round_up = (keep_digits[-1] in (0, 5))

    # Apply rounding if needed
    if do_round_up:
        idx = len(keep_digits) - 1
        while idx >= 0:
            keep_digits[idx] += 1
            if keep_digits[idx] < 10:
                break
            else:
                keep_digits[idx] = 0
                idx -= 1
                if idx < 0:
                    E += 1
