        if len(keep_digits) > sig:
            keep_digits = keep_digits[:sig]

    # Format output
    if sig > 1:
        mantissa_out = f"{keep_digits[0]}.{''.join(str(d) for d in keep_digits[1:])}"
    else:
        mantissa_out = str(keep_digits[0])

    # Range check
    if E < -999999999 or E > 999999999:
        raise ValueError("exponent out of range")

    exp_sign_str = "+" if E >= 0 else "-"
    exp_digits_out = f"{abs(E):02d}"

    sign_out = "-" if sign == '-' else ""

    return f"{sign_out}{mantissa_out}e{exp_sign_str}{exp_digits_out}"

