def snap_to_step(x: str, step: str, mode: str) -> str:
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("Inputs must be strings")
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input length exceeds 4000 characters")

    valid_modes = {"floor", "ceil", "outward", "inward", 
                   "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    pat = re.compile(r'^([+-])?(\d+\.?\d*|\.\d+)([eE]([+-]?\d{1,10}))?$')

    def parse(s):
        m = pat.match(s)
        if not m:
            raise ValueError("Invalid decimal format")
        sign_str = m.group(1)
        num_part = m.group(2)
        exp_part = m.group(4)

        if '.' in num_part:
            ip, fp = num_part.split('.', 1)
        else:
            ip, fp = num_part, ""

        digits = ip + fp
        M = int(digits)
        frac_len = len(fp)
        exp_val = int(exp_part) if exp_part else 0
        E = exp_val - frac_len
        sign = 1 if (sign_str is None or sign_str == '+') else -1
        return sign, M, E

    sx, Mx, Ex = parse(x)
    ss, Ms, Es = parse(step)

    if ss != 1 or Ms == 0:
        raise ValueError("Step must be strictly greater than zero")

    # Canonicalize step: remove trailing zeros
    while Ms % 10 == 0:
        Ms //= 10
        Es += 1
    d = max(0, -Es)

    diff = Ex - Es

    # Handle huge differences efficiently
    if diff > 3005:
        raise ValueError("Output exceeds 3000 digit limit")

    if diff >= 0:
        num = Mx * (10 ** diff)
        den = Ms
        q, r = divmod(num, den)
    else:
        if -diff > 3005:
            q, r = 0, Mx
        else:
            num = Mx
            den = Ms * (10 ** (-diff))
            q, r = divmod(num, den)

    pos_x = (sx == 1)
    cand_lower = q if pos_x else -(q + 1)
    cand_upper = q + 1 if pos_x else -q
    nearer = cand_lower if pos_x else cand_upper
    farther = cand_upper if pos_x else cand_lower

    if r == 0:
        k = cand_lower
    elif mode == "floor":
        k = cand_lower
    elif mode == "ceil":
        k = cand_upper
    elif mode == "outward":
        k = farther
    elif mode == "inward":
        k = nearer
    elif mode.startswith("tie_"):
        if 2 * r == den:
            if mode == "tie_even":
                k = cand_lower if cand_lower % 2 == 0 else cand_upper
            elif mode == "tie_odd":
                k = cand_lower if cand_lower % 2 != 0 else cand_upper
            elif mode == "tie_away":
                k = farther
            else:  # tie_zero
                k = nearer
        else:
            k = nearer

    abs_k = abs(k)
    abs_val = abs_k * Ms

    # Format output
    s = str(abs_val)
    if d == 0:
        res = s
    else:
        if len(s) <= d:
            res = "0." + "0" * (d - len(s)) + s
        else:
            p = len(s) - d
            res = s[:p] + "." + s[p:]

    if k < 0 and res != "0" * (d + 1):
        res = "-" + res

    # Size limit check
    int_part_len = max(len(s) - d, 1) if d > 0 else len(s)
    if int_part_len + d > 3000:
        raise ValueError("Output exceeds 3000 digit limit")

    return res

