                frac_part = ""
            else:
                if len(s_num) <= d:
                    int_part = "0"
                    frac_part = s_num.zfill(d)
                else:
                    int_part = s_num[:-d]
                    frac_part = s_num[-d:]
            res_str = int_part + "." + frac_part if d > 0 else int_part

            if R_num < 0:
                res_str = "-" + res_str

    # Check output size limit
    # Count digits: integer part length + d fractional digits
    if '.' in res_str:
        int_len = len(res_str.split('.')[0])
        frac_len = len(res_str.split('.')[1])
        total_digits = int_len + frac_len
    else:
        total_digits = len(res_str)

    if total_digits > 3000:
        raise ValueError("Output exceeds 3000 digits")

    return res_str
